mapper.select:
select t.address,t.city_code,t.city_code cityCode,t.name,t.tel,t.status_cd,t.status_cd
statusCd,t.community_id,t.community_id communityId,t.ext_community_id,t.ext_community_id extCommunityId,
t.lat,t.lng
from s_community t

    left join s_community_member cm on t.community_id = cm.community_id and cm.status_cd = '0'

where 1 =1

    and cm.member_id = #{memberId}


    and t.address= #{address}


    and t.city_code= #{cityCode}


    and t.name= #{name}


    and t.tel= #{tel}


    and t.status_cd= #{statusCd}


    and t.community_id= #{communityId}


    and t.community_id in

        #{item}



    and t.ext_community_id= #{extCommunityId}

order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
update s_community t set t.status_cd = #{statusCd}

    ,t.b_id = #{newBId}


    , t.address= #{address}


    , t.city_code= #{cityCode}


    , t.name= #{name}


    , t.tel= #{tel}


    , t.ext_community_id= #{extCommunityId}


    , t.lat= #{lat}


    , t.lng= #{lng}

where 1=1

    and t.community_id= #{communityId}

